//! Inputs of the GDI+ closeness report (spec 6.2). The target-size gate set is committed under
//! `fixtures/image/closeness/inputs`; the resize and JPEG sets are regenerated by the report.

use std::fs::File;
use std::io::BufWriter;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result};
use image::codecs::jpeg::JpegEncoder;
use image::imageops::{self, FilterType};
use image::{ImageFormat, Rgb, RgbImage, Rgba, RgbaImage};
use png::{BitDepth, ColorType, ScaledFloat, SrgbRenderingIntent};

use crate::golden::Paths;
use crate::prng::Prng;
use crate::srgb_profile::srgb_profile;
use crate::synthetic;

const ICON_SIDE: u32 = 64;
const BANNER_PLACEHOLDER: &str = "ph_banner";
const PLACEHOLDERS: [&str; 5] = [
    "ph_cover",
    "ph_background",
    "ph_icon",
    "ph_banner",
    "ph_screenshot",
];
const PLACEHOLDER_SCALE: f64 = 1.5;
const GAMMA_1_0_SCALED: u32 = 100_000;
const PALETTE_ENTRIES: usize = 256;
const CLOSENESS_SEED: u64 = 62;
const OPAQUE: u8 = 255;

const PHOTO_RESIZE_SIZE: (u32, u32) = (1200, 800);
const PHOTO_RESIZE_QUALITY: u8 = 90;
const PHOTO_JPEG_SIZE: (u32, u32) = (900, 600);
const PHOTO_JPEG_QUALITIES: [u8; 2] = [75, 95];
const ALPHA_GRADIENT_SIZE: (u32, u32) = (640, 480);
const DOWNSCALE_ICON_SIDE: u32 = 300;
const UPSCALE_SIZE: (u32, u32) = (100, 60);

pub fn gate_directory(paths: &Paths) -> PathBuf {
    paths.closeness().join("inputs")
}

/// `cargo xtask closeness-inputs`: writes the 13 gate inputs under `fixtures/`.
pub fn write_gate_inputs() -> Result<()> {
    let paths = Paths::new()?;
    let directory = gate_directory(&paths);
    std::fs::create_dir_all(&directory)?;
    for name in write_gate_set(&paths, &directory)? {
        println!("{name}");
    }
    Ok(())
}

fn synthetic_crop(name: &str, width: u32, height: u32) -> Result<RgbaImage> {
    let image = synthetic::all_synthetic_images()
        .into_iter()
        .find_map(|(candidate, image)| (candidate == name).then_some(image))
        .with_context(|| format!("no synthetic image named {name}"))?;
    Ok(imageops::crop_imm(&image, 0, 0, width, height).to_image())
}

fn placeholder(paths: &Paths, name: &str) -> Result<RgbaImage> {
    let path = paths.inputs().join(format!("{name}.png"));
    Ok(image::open(&path)
        .with_context(|| format!("cannot read {}", path.display()))?
        .to_rgba8())
}

fn random_bytes(prng: &mut Prng, count: usize) -> Vec<u8> {
    (0..count).map(|_| prng.next_byte()).collect()
}

/// The chunk that describes the colour space of a PNG input, if any.
enum ColourChunk {
    None,
    Gamma(u32),
    Srgb,
    IccProfile,
}

struct PngInput {
    width: u32,
    height: u32,
    color_type: ColorType,
    bit_depth: BitDepth,
    data: Vec<u8>,
    palette: Option<Vec<u8>>,
    transparency: Option<Vec<u8>>,
    colour_chunk: ColourChunk,
}

impl PngInput {
    fn new(width: u32, height: u32, color_type: ColorType, data: Vec<u8>) -> Self {
        Self {
            width,
            height,
            color_type,
            bit_depth: BitDepth::Eight,
            data,
            palette: None,
            transparency: None,
            colour_chunk: ColourChunk::None,
        }
    }

    fn rgba(image: &RgbaImage) -> Self {
        Self::new(
            image.width(),
            image.height(),
            ColorType::Rgba,
            image.as_raw().clone(),
        )
    }

    fn rgb(image: &RgbaImage) -> Self {
        let rgb: Vec<u8> = image
            .pixels()
            .flat_map(|pixel| [pixel[0], pixel[1], pixel[2]])
            .collect();
        Self::new(image.width(), image.height(), ColorType::Rgb, rgb)
    }

    fn with_colour_chunk(mut self, colour_chunk: ColourChunk) -> Self {
        self.colour_chunk = colour_chunk;
        self
    }

    fn write(&self, path: &Path) -> Result<()> {
        let file =
            File::create(path).with_context(|| format!("cannot create {}", path.display()))?;
        let mut info = png::Info::with_size(self.width, self.height);
        info.color_type = self.color_type;
        info.bit_depth = self.bit_depth;
        info.palette = self.palette.clone().map(Into::into);
        info.trns = self.transparency.clone().map(Into::into);
        match self.colour_chunk {
            ColourChunk::None | ColourChunk::Srgb => {}
            ColourChunk::Gamma(scaled) => {
                info.source_gamma = Some(ScaledFloat::from_scaled(scaled))
            }
            ColourChunk::IccProfile => info.icc_profile = Some(srgb_profile().into()),
        }
        let mut encoder = png::Encoder::with_info(BufWriter::new(file), info)?;
        if let ColourChunk::Srgb = self.colour_chunk {
            encoder.set_source_srgb(SrgbRenderingIntent::Perceptual);
        }
        let mut writer = encoder.write_header()?;
        writer.write_image_data(&self.data)?;
        writer.finish()?;
        Ok(())
    }
}

fn palette_input(prng: &mut Prng, with_transparency: bool) -> PngInput {
    let pixels = (ICON_SIDE * ICON_SIDE) as usize;
    let mut input = PngInput::new(
        ICON_SIDE,
        ICON_SIDE,
        ColorType::Indexed,
        random_bytes(prng, pixels),
    );
    input.palette = Some(random_bytes(prng, PALETTE_ENTRIES * 3));
    if with_transparency {
        input.transparency = Some(random_bytes(prng, PALETTE_ENTRIES));
    }
    input
}

fn sixteen_bit_input(prng: &mut Prng) -> PngInput {
    let samples = (ICON_SIDE * ICON_SIDE * 4 * 2) as usize;
    let mut input = PngInput::new(
        ICON_SIDE,
        ICON_SIDE,
        ColorType::Rgba,
        random_bytes(prng, samples),
    );
    input.bit_depth = BitDepth::Sixteen;
    input
}

fn write_bmp(image: &RgbaImage, with_alpha: bool, path: &Path) -> Result<()> {
    let written = if with_alpha {
        image.save_with_format(path, ImageFormat::Bmp)
    } else {
        rgb_of(image).save_with_format(path, ImageFormat::Bmp)
    };
    written.with_context(|| format!("cannot write {}", path.display()))
}

fn rgb_of(image: &RgbaImage) -> RgbImage {
    RgbImage::from_fn(image.width(), image.height(), |x, y| {
        let pixel = image.get_pixel(x, y);
        Rgb([pixel[0], pixel[1], pixel[2]])
    })
}

/// Writes the gate inputs into `directory` and returns their file names.
pub fn write_gate_set(paths: &Paths, directory: &Path) -> Result<Vec<String>> {
    let mut prng = Prng::with_seed(CLOSENESS_SEED);
    let alpha_noise = synthetic_crop("alphanoise", ICON_SIDE, ICON_SIDE)?;
    let noise = synthetic_crop("noise", ICON_SIDE, ICON_SIDE)?;
    let pixels = (ICON_SIDE * ICON_SIDE) as usize;

    let pngs = [
        ("png_rgba", PngInput::rgba(&alpha_noise)),
        ("png_rgb", PngInput::rgb(&noise)),
        ("png_palette", palette_input(&mut prng, false)),
        ("png_palette_trns", palette_input(&mut prng, true)),
        (
            "png_gray",
            PngInput::new(
                ICON_SIDE,
                ICON_SIDE,
                ColorType::Grayscale,
                random_bytes(&mut prng, pixels),
            ),
        ),
        (
            "png_gray_alpha",
            PngInput::new(
                ICON_SIDE,
                ICON_SIDE,
                ColorType::GrayscaleAlpha,
                random_bytes(&mut prng, pixels * 2),
            ),
        ),
        ("png_16bit", sixteen_bit_input(&mut prng)),
        (
            "png_gamma_1_0",
            PngInput::rgb(&noise).with_colour_chunk(ColourChunk::Gamma(GAMMA_1_0_SCALED)),
        ),
        (
            "png_srgb_chunk",
            PngInput::rgb(&noise).with_colour_chunk(ColourChunk::Srgb),
        ),
        (
            "png_iccp",
            PngInput::rgb(&noise).with_colour_chunk(ColourChunk::IccProfile),
        ),
        (
            "png_banner",
            PngInput::rgba(&placeholder(paths, BANNER_PLACEHOLDER)?),
        ),
    ];
    let mut names = Vec::new();
    for (name, input) in pngs {
        let file = format!("{name}.png");
        input.write(&directory.join(&file))?;
        names.push(file);
    }
    for (name, with_alpha) in [("bmp_24", false), ("bmp_32", true)] {
        let file = format!("{name}.bmp");
        let source = if with_alpha { &alpha_noise } else { &noise };
        write_bmp(source, with_alpha, &directory.join(&file))?;
        names.push(file);
    }
    names.sort();
    Ok(names)
}

fn fraction(position: u32, extent: u32) -> f64 {
    f64::from(position) / f64::from(extent.max(2) - 1)
}

fn channel(value: f64) -> u8 {
    (value.clamp(0.0, 1.0) * f64::from(OPAQUE)).round() as u8
}

/// A synthetic outdoor scene: sky gradient, sun, sine hills, a picket fence and fine grain, drawn
/// in normalised coordinates so every size shows the same picture.
fn photo_like_scene(width: u32, height: u32) -> RgbImage {
    let mut prng = Prng::with_seed(CLOSENESS_SEED);
    RgbImage::from_fn(width, height, |x, y| {
        let u = fraction(x, width);
        let v = fraction(y, height);
        let grain = (f64::from(prng.next_byte()) / f64::from(OPAQUE) - 0.5) * 0.08;
        let horizon = 0.55 + 0.06 * (u * 9.0).sin() + 0.03 * (u * 23.0 + 1.0).sin();
        let sun_distance = ((u - 0.72).powi(2) + ((v - 0.22) * 1.5).powi(2)).sqrt();
        let [red, green, blue] = if v < horizon {
            let sun = (1.0 - (sun_distance - 0.08) / 0.02).clamp(0.0, 1.0);
            let sky = [0.35 + 0.4 * v, 0.55 + 0.3 * v, 0.95 - 0.1 * v];
            [
                sky[0] + (1.0 - sky[0]) * sun,
                sky[1] + (0.95 - sky[1]) * sun,
                sky[2] + (0.7 - sky[2]) * sun,
            ]
        } else {
            let depth = (v - horizon) / (1.0 - horizon);
            let fence = v > 0.72 && v < 0.9 && (u * 60.0).fract() < 0.35;
            if fence {
                [0.92, 0.9, 0.86]
            } else {
                let stripes = 0.05 * (u * 140.0 + depth * 30.0).sin();
                [
                    0.25 + 0.2 * depth + stripes,
                    0.45 - 0.15 * depth + stripes,
                    0.15,
                ]
            }
        };
        Rgb([
            channel(red + grain),
            channel(green + grain),
            channel(blue + grain),
        ])
    })
}

fn alpha_gradient(width: u32, height: u32) -> RgbaImage {
    RgbaImage::from_fn(width, height, |x, y| {
        let u = fraction(x, width);
        let v = fraction(y, height);
        Rgba([
            channel(u),
            channel(v),
            channel(1.0 - u),
            channel((u + v) / 2.0),
        ])
    })
}

/// An icon: a shaded disc with a soft edge and a ring, on a transparent background whose hidden
/// colour is magenta, so a filter that blends straight colour shows a magenta fringe.
fn downscale_icon(side: u32) -> RgbaImage {
    RgbaImage::from_fn(side, side, |x, y| {
        let u = fraction(x, side) - 0.5;
        let v = fraction(y, side) - 0.5;
        let distance = (u * u + v * v).sqrt();
        let disc = ((0.4 - distance) / 0.02).clamp(0.0, 1.0);
        let ring = (1.0 - ((distance - 0.3).abs() / 0.015)).clamp(0.0, 1.0);
        if disc == 0.0 {
            return Rgba([OPAQUE, 0, OPAQUE, 0]);
        }
        let shade = 0.5 + u - v;
        Rgba([
            channel(0.1 + 0.5 * shade + ring),
            channel(0.3 + 0.4 * shade + ring),
            channel(0.8 - 0.3 * shade + ring),
            channel(disc),
        ])
    })
}

fn write_rgba_png(image: &RgbaImage, path: &Path) -> Result<()> {
    image
        .save_with_format(path, ImageFormat::Png)
        .with_context(|| format!("cannot write {}", path.display()))
}

fn write_jpeg(image: &RgbImage, quality: u8, path: &Path) -> Result<()> {
    let file = File::create(path).with_context(|| format!("cannot create {}", path.display()))?;
    JpegEncoder::new_with_quality(BufWriter::new(file), quality)
        .encode_image(image)
        .with_context(|| format!("cannot write {}", path.display()))
}

fn scaled_placeholder(paths: &Paths, name: &str) -> Result<RgbaImage> {
    let image = placeholder(paths, name)?;
    let width = (f64::from(image.width()) * PLACEHOLDER_SCALE).round() as u32;
    let height = (f64::from(image.height()) * PLACEHOLDER_SCALE).round() as u32;
    Ok(imageops::resize(
        &image,
        width,
        height,
        FilterType::Lanczos3,
    ))
}

/// Writes the resize set (every input off any target size) into `directory`.
pub fn write_resize_set(paths: &Paths, directory: &Path) -> Result<()> {
    let (photo_width, photo_height) = PHOTO_RESIZE_SIZE;
    write_jpeg(
        &photo_like_scene(photo_width, photo_height),
        PHOTO_RESIZE_QUALITY,
        &directory.join(format!("photo_like_{photo_width}x{photo_height}.jpg")),
    )?;
    let (gradient_width, gradient_height) = ALPHA_GRADIENT_SIZE;
    write_rgba_png(
        &alpha_gradient(gradient_width, gradient_height),
        &directory.join(format!(
            "alpha_gradient_{gradient_width}x{gradient_height}.png"
        )),
    )?;
    write_rgba_png(
        &downscale_icon(DOWNSCALE_ICON_SIDE),
        &directory.join(format!(
            "icon_{DOWNSCALE_ICON_SIDE}x{DOWNSCALE_ICON_SIDE}.png"
        )),
    )?;
    let (tiny_width, tiny_height) = UPSCALE_SIZE;
    write_rgba_png(
        &synthetic_crop("noise", tiny_width, tiny_height)?,
        &directory.join(format!("tiny_{tiny_width}x{tiny_height}.png")),
    )?;
    for name in PLACEHOLDERS {
        let image = scaled_placeholder(paths, name)?;
        write_rgba_png(
            &image,
            &directory.join(format!("{name}_{}x{}.png", image.width(), image.height())),
        )?;
    }
    Ok(())
}

/// Writes the JPEG decode set (the photo-like scene at cover size) into `directory`.
pub fn write_jpeg_set(directory: &Path) -> Result<()> {
    let (width, height) = PHOTO_JPEG_SIZE;
    let scene = photo_like_scene(width, height);
    for quality in PHOTO_JPEG_QUALITIES {
        write_jpeg(
            &scene,
            quality,
            &directory.join(format!("photo_like_{width}x{height}_q{quality}.jpg")),
        )?;
    }
    Ok(())
}
